output:
upstream backend {
    least_conn;
    server 10.0.0.10:8080 weight=3 max_fails=3 fail_timeout=30s;
    server 10.0.0.11:8080 weight=2 max_fails=3 fail_timeout=30s;
    server 10.0.0.12:8080 backup;
    keepalive 32;
}

upstream api {
    ip_hash;
    server 10.0.0.20:8080;
    server 10.0.0.21:8080;
    server 10.0.0.22:8080 down;
    keepalive 64;
}

upstream static {
    random two least_conn;
    server 10.0.0.30:8080;
    server 10.0.0.31:8080;
    server 10.0.0.32:8080;
    keepalive 16;
}

upstream websocket {
    hash $remote_addr consistent;
    server 10.0.0.40:8080;
    server 10.0.0.41:8080;
    keepalive 8;
}

upstream grpc {
    least_time header;
    server 10.0.0.50:50051;
    server 10.0.0.51:50051;
    keepalive 32;
    keepalive_requests 1000;
}

server {
    listen 80;
    server_name example.com;
    location / {
        proxy_pass http://backend;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

upstream tcp_backend {
    zone tcp_lb 64k;
    least_conn;
    server 10.0.0.60:3306;
    server 10.0.0.61:3306;
    server 10.0.0.62:3306 backup;
}

split_clients "${remote_addr}" $variant {
    10%     "canary";
    90%     "stable";
}

upstream backup_example {
    server 10.0.0.10:8080;
    server 10.0.0.11:8080;
    server 10.0.0.12:8080 backup;
    server 10.0.0.13:8080 backup;
}

upstream hash_example {
    hash $request_uri consistent;
    server 10.0.0.70:8080;
    server 10.0.0.71:8080;
    server 10.0.0.72:8080;
}

server_name example.com;
server_name health.example.com;
server_name zone.example.com;
server_name _;
